`timescale 1ns / 1ps
//=============================================================================
// SLIME MAZE : colour sprites, made from the PNG files in art/
//   (generated by gen_art.py - edit the PNG files, not this file)
//
//   Each pixel is a 4-bit colour number (0 = transparent).
//   A palette module turns the colour number into a 12-bit {R, G, B} colour.
//   One row of a 32 x 32 sprite = 32 pixels x 4 bits = 128 bits, written in hex,
//   left pixel first.  All modules are combinational ROMs (LUTs).
//=============================================================================

//-----------------------------------------------------------------------------
// Palette for the slime, crown, pellet and icons
//-----------------------------------------------------------------------------
module art_palette (
    input  wire [3:0]  ci,
    output reg  [11:0] rgb
);
    always @* begin
        case (ci)
            4'd1 : rgb = 12'h8F8;
            4'd2 : rgb = 12'h012;
            4'd3 : rgb = 12'h474;
            4'd4 : rgb = 12'h2C4;
            4'd5 : rgb = 12'h051;
            4'd6 : rgb = 12'hFD0;
            4'd7 : rgb = 12'hF62;
            4'd8 : rgb = 12'h0AF;
            4'd9 : rgb = 12'h092;
            4'd10: rgb = 12'h000;
            4'd11: rgb = 12'hD00;
            4'd12: rgb = 12'hFFF;
            default: rgb = 12'h000;
        endcase
    end
endmodule

