//-----------------------------------------------------------------------------
// Life icon, 8 x 8 : id 0 = life left, id 1 = life lost
//-----------------------------------------------------------------------------
module art_life (
    input  wire [0:0] id,
    input  wire [2:0] row,
    input  wire [2:0] col,
    output wire [3:0] ci          // colour number, 0 = transparent
);
    reg [31:0] r;
    always @* begin
        case ({id, row})
            // life_alive
            {1'd0, 3'd1}:      r = 32'h00AAAA00;
            {1'd0, 3'd2}:      r = 32'h0AABBAA0;
            {1'd0, 3'd3}:      r = 32'h0ABBBBA0;
            {1'd0, 3'd4}:      r = 32'h0ABBBBA0;
            {1'd0, 3'd5}:      r = 32'h0AABBAA0;
            {1'd0, 3'd6}:      r = 32'h00AAAA00;
            // life_died
            {1'd1, 3'd1}:      r = 32'h00AAAA00;
            {1'd1, 3'd2}:      r = 32'h0AACCAA0;
            {1'd1, 3'd3}:      r = 32'h0ACCCCA0;
            {1'd1, 3'd4}:      r = 32'h0ACCCCA0;
            {1'd1, 3'd5}:      r = 32'h0AACCAA0;
            {1'd1, 3'd6}:      r = 32'h00AAAA00;
            default: r = 32'h0;
        endcase
    end
    assign ci = r[(3'd7 - col) * 4 +: 4];
endmodule

//-----------------------------------------------------------------------------
// Palette for the ghosts
//-----------------------------------------------------------------------------
module ghost_palette (
    input  wire [3:0]  ci,
    output reg  [11:0] rgb
);
    always @* begin
        case (ci)
            4'd1 : rgb = 12'hF58;
            4'd2 : rgb = 12'hFFF;
            4'd3 : rgb = 12'h4DF;
            4'd4 : rgb = 12'hC6F;
            4'd5 : rgb = 12'h44F;
            4'd6 : rgb = 12'h000;
            default: rgb = 12'h000;
        endcase
    end
endmodule

